SELECT CASE WHEN unit_price >= 300 THEN 'high' WHEN unit_price >= 160 THEN 'mid' ELSE 'low' END AS unit_price_bucket, order_id, ROUND(AVG(unit_price), 2) AS avg_unit_price, ROUND(AVG(quantity), 2) AS avg_quantity FROM order_items WHERE order_id IN (10, 23, 25, 31) OR quantity <= 4 GROUP BY ROLLUP(CASE WHEN unit_price >= 300 THEN 'high' WHEN unit_price >= 160 THEN 'mid' ELSE 'low' END, order_id) ORDER BY avg_unit_price DESC;
